import{_ as e,o as a,c as o,ag as d}from"./chunks/framework.BLV0JUXI.js";const u=JSON.parse('{"title":"uni-app 知识点演示工程（uniapp-demo）","description":"","frontmatter":{},"headers":[],"relativePath":"uniapp-demo/README.md","filePath":"uniapp-demo/README.md","lastUpdated":1793196275000}'),s={name:"uniapp-demo/README.md"};function n(i,t,r,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="uni-app-知识点演示工程-uniapp-demo" tabindex="-1">uni-app 知识点演示工程（uniapp-demo） <a class="header-anchor" href="#uni-app-知识点演示工程-uniapp-demo" aria-label="Permalink to &quot;uni-app 知识点演示工程（uniapp-demo）&quot;">​</a></h1><p>一套基于 <strong>最新版 uni-app（Vue 3）</strong> 的跨端学习工程：一套代码同时支持 <strong>H5 网页、Android/iOS App、微信小程序</strong>，用 <strong>32 个可交互演示页</strong> 通俗地覆盖 uni-app 开发中的全部核心知识点。每个页面都是&quot;能点、能试、能看结果&quot;的活例子，并配有中文的&quot;知识点 / 坑点&quot;讲解。</p><blockquote><p>推荐使用 <strong>HBuilderX 5.26 及以上版本</strong> 打开本项目，可视化运行到各端，零命令行配置。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#一项目简介">一、项目简介</a></li><li><a href="#二环境要求">二、环境要求</a></li><li><a href="#三快速开始">三、快速开始</a></li><li><a href="#四工程目录结构">四、工程目录结构</a></li><li><a href="#五知识点总览32-页导航">五、知识点总览（32 页导航）</a></li><li><a href="#六公共组件说明">六、公共组件说明</a></li><li><a href="#七关键配置文件解读">七、关键配置文件解读</a></li><li><a href="#八多端差异与注意事项">八、多端差异与注意事项</a></li><li><a href="#九如何新增一个演示页">九、如何新增一个演示页</a></li><li><a href="#十学习路线建议">十、学习路线建议</a></li><li><a href="#十一常见问题-faq">十一、常见问题 FAQ</a></li></ul><hr><h2 id="一、项目简介" tabindex="-1">一、项目简介 <a class="header-anchor" href="#一、项目简介" aria-label="Permalink to &quot;一、项目简介&quot;">​</a></h2><h3 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h3><ul><li>一个 <strong>学习型演示工程</strong>：不是业务模板，而是把 uni-app 的每个知识点拆成一页&quot;实验台&quot;。</li><li><strong>全中文注释</strong>：每个页面的 <code>&lt;script&gt;</code> 与关键代码行都解释了&quot;为什么这么写&quot;、&quot;各端有什么坑&quot;。</li><li><strong>多端可跑</strong>：H5、微信小程序、App（Android / iOS）三端均可运行，页面里大量使用条件编译演示&quot;一套代码差异化多端&quot;。</li><li><strong>交互优先</strong>：所有演示都能实际操作——点按钮、填表单、下拉刷新、连 WebSocket、拍照定位，而不是看截图。</li></ul><h3 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>框架</td><td>uni-app（最新版编译器）+ Vue 3</td></tr><tr><td>组件写法</td><td><code>&lt;script setup&gt;</code> 组合式 API（个别页面为演示 options API 特意保留写法）</td></tr><tr><td>状态管理</td><td>预留 Pinia 扩展位（<code>main.js</code>），工程内演示 globalData / 事件总线 / storage 轻量方案</td></tr><tr><td>样式</td><td>纯 CSS + <code>uni.scss</code> 全局变量（仅 scss 演示页使用 lang=&quot;scss&quot;）</td></tr><tr><td>开发工具</td><td>HBuilderX 5.26+（可视化运行/打包，无需自搭 CLI）</td></tr></tbody></table><h3 id="你将学到" tabindex="-1">你将学到 <a class="header-anchor" href="#你将学到" aria-label="Permalink to &quot;你将学到&quot;">​</a></h3><ul><li>应用 / 页面 / 组件三层生命周期与执行时序</li><li>数据绑定、事件系统、条件编译、rpx 适配</li><li>全部内置组件（view/text/image/scroll-view/swiper/表单/map/canvas 等）</li><li>页面路由（五大导航 API）、传参（query + eventChannel）、分包与预下载</li><li>网络请求封装、上传下载、WebSocket、数据缓存</li><li>交互反馈、设备 API（剪贴板/扫码/相机/定位）、分享、系统信息</li><li>下拉刷新 + 上拉加载的经典列表模式、跨页面通信方案选型</li></ul><hr><h2 id="二、环境要求" tabindex="-1">二、环境要求 <a class="header-anchor" href="#二、环境要求" aria-label="Permalink to &quot;二、环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>开发工具</td><td>HBuilderX 5.26+</td><td>需安装&quot;uni-app(Vue3)&quot;编译插件（首次运行会自动提示安装）</td></tr><tr><td>H5 运行</td><td>现代浏览器</td><td>无任何额外配置</td></tr><tr><td>微信小程序</td><td>微信开发者工具（稳定版）</td><td>需在开发者工具&quot;设置 → 安全&quot;中开启<strong>服务端口</strong>；用自己的小程序 appid 替换 <code>manifest.json</code> 中的测试 appid</td></tr><tr><td>App 运行</td><td>Android 真机/模拟器、iOS 真机</td><td>Android 可用 HBuilderX 内置基座；iOS 需自定义基座或证书打包</td></tr><tr><td>网络</td><td>可访问公网</td><td>部分页面使用公共演示接口（见<a href="#八多端差异与注意事项">多端差异</a>）</td></tr></tbody></table><blockquote><p>本工程 <code>manifest.json</code> 中已将小程序 <code>urlCheck</code> 关闭、声明了定位相关 <code>permission</code> 与 <code>requiredPrivateInfos</code>、App 端已勾选 Geolocation 模块，<strong>开箱即可运行全部演示</strong>。</p></blockquote><hr><h2 id="三、快速开始" tabindex="-1">三、快速开始 <a class="header-anchor" href="#三、快速开始" aria-label="Permalink to &quot;三、快速开始&quot;">​</a></h2><h3 id="方式一-运行到浏览器-h5" tabindex="-1">方式一：运行到浏览器（H5） <a class="header-anchor" href="#方式一-运行到浏览器-h5" aria-label="Permalink to &quot;方式一：运行到浏览器（H5）&quot;">​</a></h3><ol><li>HBuilderX 打开 <code>uniapp-demo</code> 目录；</li><li>菜单栏 <strong>运行 → 运行到浏览器 → Chrome</strong>；</li><li>自动打开首页，点击卡片进入任意知识点。</li></ol><h3 id="方式二-运行到微信开发者工具" tabindex="-1">方式二：运行到微信开发者工具 <a class="header-anchor" href="#方式二-运行到微信开发者工具" aria-label="Permalink to &quot;方式二：运行到微信开发者工具&quot;">​</a></h3><ol><li>打开微信开发者工具，开启 <strong>设置 → 安全 → 服务端口</strong>；</li><li>HBuilderX 中 <strong>运行 → 运行到小程序模拟器 → 微信开发者工具</strong>；</li><li>首次运行若提示 appid 无效，把 <code>manifest.json → mp-weixin.appid</code> 换成你自己的（可用测试号）。</li></ol><h3 id="方式三-运行到手机-app" tabindex="-1">方式三：运行到手机（App） <a class="header-anchor" href="#方式三-运行到手机-app" aria-label="Permalink to &quot;方式三：运行到手机（App）&quot;">​</a></h3><ol><li>手机打开 USB 调试并连接电脑；</li><li>HBuilderX <strong>运行 → 运行到手机或模拟器 → 选择你的设备</strong>；</li><li>首次运行会自动安装 HBuilder 基座，之后点&quot;运行&quot;即可热更新调试。</li></ol><h3 id="打包发布-可选" tabindex="-1">打包发布（可选） <a class="header-anchor" href="#打包发布-可选" aria-label="Permalink to &quot;打包发布（可选）&quot;">​</a></h3><ul><li><strong>H5</strong>：发行 → 网站-PC Web或手机H5，产物在 <code>unpackage/dist/build/web</code>；</li><li><strong>小程序</strong>：发行 → 小程序-微信，用微信开发者工具打开产物目录上传；</li><li><strong>App</strong>：发行 → 原生App-云打包（测试用云打包证书即可）。</li></ul><hr><h2 id="四、工程目录结构" tabindex="-1">四、工程目录结构 <a class="header-anchor" href="#四、工程目录结构" aria-label="Permalink to &quot;四、工程目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uniapp-demo/</span></span>
<span class="line"><span>├── pages.json                    # 页面路由 + tabBar + 分包 + 预下载 + easycom（核心配置）</span></span>
<span class="line"><span>├── manifest.json                 # 应用标识与各端配置（appid、权限、模块、H5 路由等）</span></span>
<span class="line"><span>├── main.js                       # 应用入口：createSSRApp 工厂 + Pinia 扩展位</span></span>
<span class="line"><span>├── App.vue                       # 应用级生命周期（onLaunch/onShow/onHide）+ globalData + 全局样式</span></span>
<span class="line"><span>├── uni.scss                      # uni-app 内置样式变量（编译期注入所有组件）</span></span>
<span class="line"><span>├── index.html                    # H5 模板</span></span>
<span class="line"><span>├── static/</span></span>
<span class="line"><span>│   └── tabbar/                   # tabBar 图标（普通态/选中态 PNG）</span></span>
<span class="line"><span>├── components/                   # easycom 自动注册组件（目录名=文件名=标签名）</span></span>
<span class="line"><span>│   ├── demo-block/demo-block.vue # 演示卡片外壳（所有页面的统一结构）</span></span>
<span class="line"><span>│   └── star-rate/star-rate.vue   # 评分组件（props / v-model / emit 教学示例）</span></span>
<span class="line"><span>├── pages/</span></span>
<span class="line"><span>│   ├── index/index.vue           # 首页：全部知识点的分组导航目录（tabBar 页）</span></span>
<span class="line"><span>│   ├── mine/mine.vue             # 我的（tabBar 页）</span></span>
<span class="line"><span>│   ├── basics/                   # 基础入门 5 页</span></span>
<span class="line"><span>│   ├── style/                    # 样式与布局 3 页</span></span>
<span class="line"><span>│   ├── components/               # 内置组件 7 页</span></span>
<span class="line"><span>│   ├── router/                   # 路由与页面 2 页</span></span>
<span class="line"><span>│   ├── network/                  # 网络请求 2 页</span></span>
<span class="line"><span>│   ├── storage/                  # 数据缓存 1 页</span></span>
<span class="line"><span>│   ├── interaction/              # 交互反馈 3 页</span></span>
<span class="line"><span>│   ├── device/                   # 设备能力 3 页</span></span>
<span class="line"><span>│   └── advanced/                 # 进阶实战 3 页</span></span>
<span class="line"><span>└── packages/</span></span>
<span class="line"><span>    └── sub/pages/detail.vue      # 分包演示页（subPackages + preloadRule 实战）</span></span></code></pre></div><hr><h2 id="五、知识点总览-32-页导航" tabindex="-1">五、知识点总览（32 页导航） <a class="header-anchor" href="#五、知识点总览-32-页导航" aria-label="Permalink to &quot;五、知识点总览（32 页导航）&quot;">​</a></h2><p>首页按以下 9 组分组导航，与 <code>pages.json</code> 注册路径一一对应。</p><h3 id="_1-基础入门" tabindex="-1">1. 基础入门 <a class="header-anchor" href="#_1-基础入门" aria-label="Permalink to &quot;1. 基础入门&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/basics/lifecycle</code></td><td>应用/页面/组件三层生命周期、onLoad 与 onShow 区别、onBackPress 拦截返回键</td></tr><tr><td><code>pages/basics/data-binding</code></td><td>ref / reactive / computed / watch / v-model 双向绑定</td></tr><tr><td><code>pages/basics/events</code></td><td>tap / longpress 事件、事件对象、@tap 传参、阻止冒泡</td></tr><tr><td><code>pages/basics/conditional</code></td><td><code>#ifdef / #ifndef / #endif</code> 条件编译，一套代码差异化多端</td></tr><tr><td><code>pages/basics/animation</code></td><td>uni.createAnimation 动画与 CSS transition 两种方案</td></tr></tbody></table><h3 id="_2-样式与布局" tabindex="-1">2. 样式与布局 <a class="header-anchor" href="#_2-样式与布局" aria-label="Permalink to &quot;2. 样式与布局&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/style/rpx</code></td><td>rpx 响应式单位：750rpx = 屏幕宽度，多端适配的核心</td></tr><tr><td><code>pages/style/scss</code></td><td>uni.scss 全局变量注入、样式作用域与 scoped</td></tr><tr><td><code>pages/style/dynamic</code></td><td>:class 对象/数组语法、:style 对象语法、一键主题切换</td></tr></tbody></table><h3 id="_3-内置组件" tabindex="-1">3. 内置组件 <a class="header-anchor" href="#_3-内置组件" aria-label="Permalink to &quot;3. 内置组件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/components/basic</code></td><td>view(hover-class) / text(selectable) / image(mode 对比+lazy-load) / button / progress / icon</td></tr><tr><td><code>pages/components/scroll</code></td><td>scroll-view 纵横向滚动、@scrolltolower 触底加载、scroll-into-view 锚点、refresher 下拉</td></tr><tr><td><code>pages/components/swiper</code></td><td>自动播放 / 循环 / 指示器、@change 监听、current 受控跳页、竖向轮播</td></tr><tr><td><code>pages/components/form</code></td><td>input / textarea / checkbox / radio / switch / slider / picker，<code>&lt;form @submit&gt;</code> 一次收集全部数据</td></tr><tr><td><code>pages/components/map</code></td><td>map 组件、markers 标记点、show-location、markertap 事件、H5 端 key 配置说明</td></tr><tr><td><code>pages/components/canvas</code></td><td>老版 canvas API 四件套（矩形/圆/线条/文字）、ctx.draw 提交、canvasToTempFilePath 导出图片</td></tr><tr><td><code>pages/components/custom</code></td><td>easycom 自动注册规则、props、v-model 协议（modelValue / update:modelValue）、slot 插槽</td></tr></tbody></table><h3 id="_4-路由与页面" tabindex="-1">4. 路由与页面 <a class="header-anchor" href="#_4-路由与页面" aria-label="Permalink to &quot;4. 路由与页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/router/navigation</code></td><td>navigateTo / redirectTo / reLaunch / switchTab / navigateBack 五大 API 速查表与页面栈规则</td></tr><tr><td><code>pages/router/params</code></td><td>url query 传参 + encodeURIComponent、onLoad(options)、eventChannel 双向通信、复杂对象传参选型</td></tr><tr><td><code>packages/sub/pages/detail</code></td><td>subPackages 分包原理、preloadRule 预下载、分包页跳转与传参</td></tr></tbody></table><h3 id="_5-网络请求" tabindex="-1">5. 网络请求 <a class="header-anchor" href="#_5-网络请求" aria-label="Permalink to &quot;5. 网络请求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/network/request</code></td><td>uni.request 的 Promise 封装模板、GET/POST、statusCode 与 fail 的区分、超时处理</td></tr><tr><td><code>pages/network/upload</code></td><td>downloadFile 下载进度条、uploadFile 上传（name/formData）、保存相册权限被拒引导 openSetting</td></tr></tbody></table><h3 id="_6-数据缓存" tabindex="-1">6. 数据缓存 <a class="header-anchor" href="#_6-数据缓存" aria-label="Permalink to &quot;6. 数据缓存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/storage/storage</code></td><td>同步/异步两套 API、对象直接存取（自动序列化）、getStorageInfoSync 容量统计、H5 localStorage 底层差异</td></tr></tbody></table><h3 id="_7-交互反馈" tabindex="-1">7. 交互反馈 <a class="header-anchor" href="#_7-交互反馈" aria-label="Permalink to &quot;7. 交互反馈&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/interaction/feedback</code></td><td>showToast 四种 icon 与 mask、showLoading/hideLoading、showModal、showActionSheet、动态导航栏标题/颜色</td></tr><tr><td><code>pages/interaction/device-api</code></td><td>剪贴板读写、makePhoneCall、vibrateShort/Long、scanCode（H5 端条件编译剔除假按钮）</td></tr><tr><td><code>pages/interaction/share</code></td><td>onShareAppMessage / onShareTimeline 注册、<code>open-type=&quot;share&quot;</code> 按钮、App uni.share 与 H5 分享方案速查</td></tr></tbody></table><h3 id="_8-设备能力" tabindex="-1">8. 设备能力 <a class="header-anchor" href="#_8-设备能力" aria-label="Permalink to &quot;8. 设备能力&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/device/system</code></td><td>getSystemInfoSync 关键字段表、getDeviceInfo/getWindowInfo/getAppBaseInfo 新 API 的 typeof 探测、platform/uniPlatform 平台判断、canIUse</td></tr><tr><td><code>pages/device/media</code></td><td>chooseImage 九宫格（count/sizeType/sourceType）、previewImage 全屏预览、chooseVideo 回放、保存相册标准权限流程</td></tr><tr><td><code>pages/device/location</code></td><td>getLocation(gcj02) 与失败分支、openLocation 查看位置、chooseLocation 地图选点、三端定位配置清单</td></tr></tbody></table><h3 id="_9-进阶实战" tabindex="-1">9. 进阶实战 <a class="header-anchor" href="#_9-进阶实战" aria-label="Permalink to &quot;9. 进阶实战&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>核心知识点</th></tr></thead><tbody><tr><td><code>pages/advanced/refresh-load</code></td><td>页面级下拉刷新（enablePullDownRefresh + stopPullDownRefresh）、onReachBottom 分页、loading/hasMore 三态管理</td></tr><tr><td><code>pages/advanced/websocket</code></td><td>uni.connectSocket / SocketTask 四大回调、心跳与指数退避重连思路、onUnload 断连、小程序 socket 域名白名单</td></tr><tr><td><code>pages/advanced/event-bus</code></td><td>getApp().globalData 读写（非响应式！）、uni.$on/$emit/$off 黄金法则（onLoad 注册、onUnload 成对解绑）</td></tr></tbody></table><hr><h2 id="六、公共组件说明" tabindex="-1">六、公共组件说明 <a class="header-anchor" href="#六、公共组件说明" aria-label="Permalink to &quot;六、公共组件说明&quot;">​</a></h2><p>两个组件均位于 <code>components/</code> 目录，遵循 <strong>easycom 规则</strong>：<code>components/组件名/组件名.vue</code>，页面中直接写标签即可，<strong>无需 import、无需 components 注册</strong>。</p><h3 id="demo-block-演示卡片外壳" tabindex="-1">demo-block（演示卡片外壳） <a class="header-anchor" href="#demo-block-演示卡片外壳" aria-label="Permalink to &quot;demo-block（演示卡片外壳）&quot;">​</a></h3><p>所有演示页的统一结构组件，让每个知识点都以&quot;标题 + 说明 + 可操作区&quot;的卡片呈现。</p><table tabindex="0"><thead><tr><th>Prop</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>title</code></td><td>String</td><td>卡片标题（绿色竖条 + 加粗文字）</td></tr><tr><td><code>desc</code></td><td>String</td><td>可选的知识点说明文字</td></tr><tr><td>默认插槽</td><td>—</td><td>页面自定义的演示内容</td></tr></tbody></table><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">demo-block</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;标题&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> desc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;说明文字&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  &lt;!-- 任意演示内容 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">demo-block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h3 id="star-rate-评分组件" tabindex="-1">star-rate（评分组件） <a class="header-anchor" href="#star-rate-评分组件" aria-label="Permalink to &quot;star-rate（评分组件）&quot;">​</a></h3><p>自定义组件三要素（props / emit / v-model）的教学范本，同时也是可复用组件。</p><table tabindex="0"><thead><tr><th>Prop</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>modelValue</code></td><td>Number</td><td>当前分数（v-model 协议字段）</td></tr><tr><td><code>max</code></td><td>Number</td><td>星星总数，默认 5</td></tr></tbody></table><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 点星星评分，再点当前分取消；一行 v-model 完成双向绑定 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">star-rate</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;score&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :max</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><hr><h2 id="七、关键配置文件解读" tabindex="-1">七、关键配置文件解读 <a class="header-anchor" href="#七、关键配置文件解读" aria-label="Permalink to &quot;七、关键配置文件解读&quot;">​</a></h2><h3 id="pages-json" tabindex="-1">pages.json <a class="header-anchor" href="#pages-json" aria-label="Permalink to &quot;pages.json&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置块</th><th>本工程的用法</th></tr></thead><tbody><tr><td><code>pages</code></td><td>31 个主包页面，首页第一个即启动页；每页通过 <code>style.navigationBarTitleText</code> 定制标题；<code>refresh-load</code> 页开启了 <code>enablePullDownRefresh</code> 与 <code>onReachBottomDistance</code></td></tr><tr><td><code>globalStyle</code></td><td>导航栏绿色（#2B9939）白字、页面底色 #F5F6F7，全局默认风格</td></tr><tr><td><code>tabBar</code></td><td>2 个 tab（首页 / 我的），选中色与主题绿一致，图标在 <code>static/tabbar/</code></td></tr><tr><td><code>subPackages</code></td><td><code>packages/sub</code> 独立分包，减小主包体积</td></tr><tr><td><code>preloadRule</code></td><td>进入&quot;页面导航&quot;页时预下载分包（network: all），消除首次进入分包页的等待</td></tr><tr><td><code>easycom</code></td><td><code>autoscan: true</code>，<code>components/</code> 目录下组件自动按需注册</td></tr></tbody></table><blockquote><p><strong>注意</strong>：JSON 文件不允许写注释（HBuilderX 会报错），本工程的 <code>pages.json</code> 与 <code>manifest.json</code> 均为无注释最终版；配置含义见本节与本 README。</p></blockquote><h3 id="manifest-json" tabindex="-1">manifest.json <a class="header-anchor" href="#manifest-json" aria-label="Permalink to &quot;manifest.json&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>本工程的用法</th></tr></thead><tbody><tr><td><code>vueVersion: &quot;3&quot;</code></td><td>使用 Vue 3 编译器</td></tr><tr><td><code>mp-weixin.appid</code></td><td>测试 appid，运行前建议换成自己的</td></tr><tr><td><code>mp-weixin.urlCheck</code></td><td>已关闭（学习用），生产请打开并配置合法域名</td></tr><tr><td><code>mp-weixin.permission</code> + <code>requiredPrivateInfos</code></td><td>定位弹窗用途描述 + getLocation/chooseLocation 接口声明（小程序审核必需）</td></tr><tr><td><code>app-plus.modules.Geolocation</code></td><td>App 端定位模块</td></tr><tr><td><code>h5.router.mode: &quot;hash&quot;</code></td><td>H5 使用 hash 路由，静态托管无需服务端 rewrite</td></tr><tr><td><code>h5.title</code></td><td>浏览器标签页标题</td></tr></tbody></table><hr><h2 id="八、多端差异与注意事项" tabindex="-1">八、多端差异与注意事项 <a class="header-anchor" href="#八、多端差异与注意事项" aria-label="Permalink to &quot;八、多端差异与注意事项&quot;">​</a></h2><p>工程内每个页面对涉及的差异都有注释，这里汇总最容易踩的坑：</p><h3 id="网络与域名" tabindex="-1">网络与域名 <a class="header-anchor" href="#网络与域名" aria-label="Permalink to &quot;网络与域名&quot;">​</a></h3><ul><li><strong>小程序端</strong>：request / uploadFile / downloadFile / WebSocket 的域名必须配置到小程序后台的合法域名列表；本工程已关闭 <code>urlCheck</code> 仅用于本地学习，真机预览与上线前必须恢复。</li><li><strong>H5 端</strong>：存在浏览器跨域。开发期可在 <code>manifest.json → h5.devServer.proxy</code> 配置代理；生产环境靠 Nginx 反代或后端 CORS。</li><li><strong>App 端</strong>：无跨域概念。</li><li>演示接口为公共测试服务，偶发不稳定属正常：<code>jsonplaceholder.typicode.com</code>（增删改查）、<code>httpbin.org</code>（上传回显/超时模拟）、<code>wss://echo.websocket.events</code>（回声服务器）、<code>web-assets.dcloud.net.cn</code>（官方示例图床）。</li></ul><h3 id="平台能力差异-工程内均有条件编译示例" tabindex="-1">平台能力差异（工程内均有条件编译示例） <a class="header-anchor" href="#平台能力差异-工程内均有条件编译示例" aria-label="Permalink to &quot;平台能力差异（工程内均有条件编译示例）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>能力</th><th>H5</th><th>微信小程序</th><th>App</th></tr></thead><tbody><tr><td>扫码 <code>scanCode</code></td><td>✗（页面里已用 <code>#ifdef H5</code> 替换为提示）</td><td>✓</td><td>✓</td></tr><tr><td>保存相册</td><td>✗（<code>#ifndef H5</code> 剔除）</td><td>✓（需授权）</td><td>✓（需授权）</td></tr><tr><td>map 组件</td><td>需在 <code>h5.sdkConfigs.maps</code> 配高德/腾讯 key</td><td>内置可用</td><td>内置可用（TIF/高德）</td></tr><tr><td>分享</td><td>无通用 API（复制链接/JS-SDK）</td><td>右上角转发 + open-type=share</td><td>uni.share（需配 SDK）</td></tr><tr><td>页面栈上限</td><td>无限制</td><td>10 层</td><td>100 层</td></tr><tr><td>定位</td><td>需 https + 浏览器授权</td><td>需后台开通接口权限 + manifest 声明</td><td>需 Geolocation 模块</td></tr></tbody></table><h3 id="高频坑点-页面注释中有详细展开" tabindex="-1">高频坑点（页面注释中有详细展开） <a class="header-anchor" href="#高频坑点-页面注释中有详细展开" aria-label="Permalink to &quot;高频坑点（页面注释中有详细展开）&quot;">​</a></h3><ol><li><code>uni.request</code> 的 HTTP 404/500 也走 <code>success</code> 回调，必须手动判断 <code>statusCode</code>。</li><li><code>swiper</code> 默认高度 150px 且不随内容撑开，必须显式设置高度。</li><li><code>image</code> 不设 <code>mode</code> 时默认 <code>scaleToFill</code> 会拉伸变形，常用 <code>widthFix</code>。</li><li><code>onPullDownRefresh</code> 处理完必须调用 <code>uni.stopPullDownRefresh()</code>。</li><li><code>uni.$on</code> 必须在 <code>onUnload</code> 中 <code>uni.$off</code> 成对解绑，否则重复监听（最经典的内存泄漏）。</li><li>小程序端 <code>map</code>、<code>video</code> 等是原生组件，层级最高，普通 <code>view</code> 盖不住，需要 <code>cover-view</code>。</li><li><code>globalData</code> 不是响应式的，改完其他页面不会自动刷新。</li><li>保存相册/定位授权被拒后系统不再弹窗，必须引导用户 <code>uni.openSetting</code>。</li></ol><hr><h2 id="九、如何新增一个演示页" tabindex="-1">九、如何新增一个演示页 <a class="header-anchor" href="#九、如何新增一个演示页" aria-label="Permalink to &quot;九、如何新增一个演示页&quot;">​</a></h2><p>三步完成（可对照现有任意页面抄结构）：</p><ol><li><strong>建文件</strong>：在对应板块目录下新建 <code>pages/xxx/my-demo.vue</code>，沿用统一骨架—— <ul><li>顶部中文注释块（知识点 / 坑点）；</li><li><code>&lt;template&gt;</code> 里用 <code>&lt;demo-block&gt;</code> 卡片承载演示内容；</li><li><code>&lt;script setup&gt;</code> 组合式 API，页面生命周期从 <code>@dcloudio/uni-app</code> 导入；</li><li>纯 CSS，<code>page</code> 内边距 24rpx，主题色 #2B9939。</li></ul></li><li><strong>注册路由</strong>：在 <code>pages.json → pages</code> 数组中追加 <code>{ &quot;path&quot;: &quot;pages/xxx/my-demo&quot;, &quot;style&quot;: { &quot;navigationBarTitleText&quot;: &quot;标题&quot; } }</code>。</li><li><strong>加导航入口</strong>：在 <code>pages/index/index.vue</code> 的 <code>groups</code> 数组对应分组里追加 <code>{ title, desc, url }</code> 项。</li></ol><blockquote><p>记住三条硬规则：跳转 url 以 <code>/</code> 开头且必须在 pages.json 注册过；<code>switchTab</code> 只能跳 tabBar 页；JSON 配置文件不能写注释。</p></blockquote><hr><h2 id="十、学习路线建议" tabindex="-1">十、学习路线建议 <a class="header-anchor" href="#十、学习路线建议" aria-label="Permalink to &quot;十、学习路线建议&quot;">​</a></h2><p><strong>第 1 天 · 基础入门</strong>：按首页顺序走完&quot;基础入门 + 样式与布局&quot;8 页，重点理解生命周期时序与 rpx 适配，这是后面一切的地基。</p><p><strong>第 2 天 · 组件与页面</strong>：走完&quot;内置组件 + 路由与页面&quot;10 页。动手要求：用 scroll-view 改造一个触底加载列表；让 swiper 的页码跟随 @change 变化；从首页带参数跳到分包页。</p><p><strong>第 3 天 · 数据与网络</strong>：走完&quot;网络请求 + 数据缓存&quot;3 页。动手要求：把 request.vue 的 Promise 封装抄进自己的项目；完成一次&quot;下载图片 → 预览 → 保存相册&quot;完整链路。</p><p><strong>第 4 天 · 设备与交互</strong>：走完&quot;交互反馈 + 设备能力&quot;6 页，真机体验（振动、扫码、定位在浏览器里没有效果）。重点记住每个 API 的失败分支怎么写。</p><p><strong>第 5 天 · 进阶实战</strong>：走完&quot;进阶实战&quot;3 页，然后做综合练习：<strong>从零写一个&quot;待办清单&quot;</strong>——列表下拉刷新 + 上拉分页（refresh-load 模式）、编辑页用 eventChannel 回传结果（params 模式）、token 用 storage 持久化、删除前 showModal 确认。</p><hr><h2 id="十一、常见问题-faq" tabindex="-1">十一、常见问题 FAQ <a class="header-anchor" href="#十一、常见问题-faq" aria-label="Permalink to &quot;十一、常见问题 FAQ&quot;">​</a></h2><p><strong>Q1：运行到微信开发者工具时报&quot;appid 无效&quot;或直接白名单报错？</strong> 把 <code>manifest.json → mp-weixin.appid</code> 换成自己注册的小程序 appid（或注册测试号）；域名报错确认 <code>urlCheck</code> 是否被工具重置，学习期可再次关闭。</p><p><strong>Q2：H5 端地图空白？</strong> 在 <code>manifest.json → h5.sdkConfigs.maps</code> 配置高德或腾讯地图的 key（申请免费），小程序/App 端无此要求。</p><p><strong>Q3：网络请求页 404 或一直失败？</strong> 演示接口依赖公网，先确认电脑/手机能访问 <code>jsonplaceholder.typicode.com</code>；小程序端检查合法域名配置；H5 端多为跨域，配置 devServer.proxy。</p><p><strong>Q4：真机上定位/保存相册没反应？</strong> 多半是权限曾被拒绝——系统不会再弹窗。页面里已内置 <code>uni.openSetting</code> 引导；也可以删掉 App 重装重走授权流程。</p><p><strong>Q5：扫码、振动在浏览器里没效果？</strong> 正常。这两个能力 H5 端不支持，工程里已用条件编译处理（H5 显示替代提示）。请在真机或小程序端体验。</p><p><strong>Q6：WebSocket 连不上？</strong><code>wss://echo.websocket.events</code> 是公共回声服务，偶发限流；小程序端还需把该域名加入 socket 合法域名。断开后点&quot;重连&quot;即可。</p><p><strong>Q7：页面跳转报错 &quot;can not navigateTo a tabbar page&quot;？</strong> 跳转目标在 tabBar 里时只能用 <code>uni.switchTab</code>，详见&quot;页面导航&quot;页的速查表。</p><p><strong>Q8：怎么快速定位某个知识点在哪个页面？</strong> 打开首页（导航目录）按 9 个分组找；或直接在本 README 的<a href="#五知识点总览32-页导航">知识点总览</a>中 Ctrl+F 搜索关键词。</p>`,101)])])}const b=e(s,[["render",n]]);export{u as __pageData,b as default};
